out = {}
# walk recursively
def walk(path):
    out[path] = None
    for entry in repo.list(path):
        full = (path.rstrip("/") + "/" + entry) if path != "." else entry
        if entry.endswith("/"):
            walk(full)
        else:
            out[full] = repo.read(full)

walk(".")
out["_src_legacy_hits"] = ["%s:%d" % (r.path, r.line) for r in repo.search("legacy_flag", glob = "src/**")]
out["_src_modern_hits"] = ["%s:%d" % (r.path, r.line) for r in repo.search("modern_flag", glob = "src/**")]
out["_repo_legacy_hits"] = ["%s:%d" % (r.path, r.line) for r in repo.search("legacy_flag", glob = "**")]
return out
